esbmc_test_source:
contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address recipient) public payable {
        // No restriction on recipient; migrateTo is called by this test contract,
        // so it either succeeds or reverts.  There is no deposited balance here.
        uint256 beforeBalance = address(c).balance;
        uint256 beforeRecipient = recipient.balance;

        bool reverted;
        c.migrateTo(recipient); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterBalance = address(c).balance;
        uint256 afterRecipient = recipient.balance;

        // General rule: if the call reverted, c's balance is unchanged.
        // If it succeeded, c transferred its entire prior balance to recipient,
        // so c now has zero balance and recipient received exactly beforeBalance.
        assert(
            (reverted && afterBalance == beforeBalance) ||
            (!reverted && afterBalance == 0 && afterRecipient == beforeRecipient + beforeBalance)
        );
    }

    receive() external payable {}
}

