// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _run(address recipient) internal {
        uint256 beforeBalance = address(c).balance;
        uint256 beforeRecipient = recipient.balance;
        bool reverted;
        try c.migrateTo(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterBalance = address(c).balance;
        uint256 afterRecipient = recipient.balance;
        assertTrue((reverted && afterBalance == beforeBalance) ||
            (!reverted && afterBalance == 0 && afterRecipient == beforeRecipient + beforeBalance));
    }

    function testFuzz_run(address recipient) public {
        vm.assume(recipient.code.length == 0 && uint160(recipient) > 0xffff && recipient != address(this) && recipient != address(c) && recipient != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && recipient != 0x000000000000000000636F6e736F6c652e6c6f67 && recipient != 0x4e59b44847b379578588920cA78FbF26c0B4956C && recipient != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(recipient);
    }

    receive() external payable {}
}
